/**
 * Zero-credit cold-start guide for MCP clients.
 */

export type GuideWorkflow =
  | 'quick_verify'
  | 'document_quote'
  | 'document_review'
  | 'source_trace'
  | 'numeric'
  | 'billing'
  | 'folders'
  | 'choose';

export function resolveGuideWorkflow(raw: unknown): GuideWorkflow {
  if (
    raw === 'quick_verify' ||
    raw === 'document_quote' ||
    raw === 'document_review' ||
    raw === 'source_trace' ||
    raw === 'numeric' ||
    raw === 'billing' ||
    raw === 'folders' ||
    raw === 'choose'
  ) {
    return raw;
  }
  return 'choose';
}

/** Shared reference paragraphs. Workflows include only the ones they need; billing lists them all. */
const EMAIL_OTP_DELIVERY =
  'Email OTP login and resend-code requests return HTTP 503 when email delivery is disabled or fails, rather than reporting that the code was sent. These requests do not automatically retry delivery; retry manually after delivery becomes available.';
const BOT_RATE_LIMIT =
  'Bot-authenticated article routes enforce the configured per-minute request limit of the validated key for each key, HTTP method and route. Newly created keys default to 60; a legacy validation result with missing limit metadata alone retains 100. Limits must be integers from 1 to 2147483647. Null or invalid stored settings return a useful configuration error (503), while disabled keys remain unauthorized (401). Exhausting the request limit returns 403. The shared Redis counter keeps a 60-second window from its first request; during a counter outage, the same quota uses the existing process-local memory fallback, whose counters are not shared across processes.';
const FREE_RENEWAL =
  'New reservations record their billing period. On a server implementing the no-carry renewal policy, free-plan renewal restores the full monthly allocation and leaves prior-period reservations and their references unchanged. Work still running at period end stays charged to that closing period; its later release or partial settlement cannot refund unrelated spending in the new period. A reconciliation_required outcome remains unresolved, including for the run budget, rather than becoming a free result or a reason to repeat paid work. Source findings analysis keeps a provider reply that stopped before completion, for example at its output token limit, and never replays it as a result. Because the provider answered, that attempt settles at zero credits and its token usage stays on the attempt record. The next explicit analyze request dispatches a fresh attempt under its own reservation, for single-prompt stages and multi-batch claims alike, at most three attempts per stage. If the third attempt also stops, the request fails with HTTP 422 source_findings_provider_incomplete_exhausted, and repeating the same request cannot succeed. A provider reply that finishes but is not valid JSON also settles at zero credits, counts toward those three attempts and is retried once with the same input while attempts remain; if the retry is also invalid, the request fails with retryable HTTP 502 model_output_invalid and a later analyze request can try again, but an invalid reply on the third attempt fails at once with HTTP 422 source_findings_provider_incomplete_exhausted, marked retryable: false. An unknown provider outcome still remains reconciliation_required and is not retried. A change to comparison-only thinking settings reuses accepted claims and re-runs only the comparison. If a request ends after keeping a stopped reply but before settling it, the next analyze request settles that earlier attempt at zero credits before dispatching the next one. Attempts settled at zero do not count against the 10-credit ceiling of an analysis run. The claims stage stays on the ceiling of the run that first dispatched it, so a run that dispatches both stages shares one ceiling between them, while a run that reuses claims from an earlier run leaves that claims spend on the ceiling of the earlier run and gives its comparison a fresh 10-credit ceiling.';
const PAID_RENEWAL =
  'Paid-plan renewal uses valid billing-period start and end dates from the provider. On servers implementing the provider-period correction, activation stores a valid provider period instead of a processing-time approximation; missing or invalid activation dates keep the 30-day fallback. Renewal must advance the saved credit period start and end and cannot overlap the saved provider period or rewind subscription metadata. A legacy processing-time fallback ending after the first calendar renewal starts does not by itself make that renewal stale. An admitted renewal writes the credit balance and subscription metadata in one transaction. On a server implementing the no-carry renewal policy, the new allocation is replenished in full without carrying earlier reservations or rebinding their references; this remains true when unresolved earlier reservations exceed the new allocation; period-attributed reservations stay charged to their closing period, and later release or partial settlement cannot subtract from unrelated new-period spending. The current positive allocation is retained for an unchanged plan; a known plan change uses its published allocation. Distinct events for the same or an older period cannot reset later spend or rewind subscription metadata. A missing or invalid period or a failed renewal write stays a failed, unprocessed webhook rather than reporting a successful renewal.';
const HISTORICAL_REFUNDS =
  'On servers implementing no-carry renewal, a historical bare subscription reference has an unknown billing period. A positive refund against it refuses with explicit reconciliation required rather than using later-period spending as proof of held credits; the operator release dry run refuses the same ambiguous refund. A modern reference refunds unused credits only when its represented period matches the current ledger and enough liability remains; an older-period refund returns zero to the new balance. No refund is invented for a null reference or zero unused credits. Missing historical periods are not guessed from creation timestamps, existing reservations remain unchanged, and operation receipts keep their existing subscription-reference shape. Verify the serving release policy before relying on this contract; this guide does not prove that every live server has activated no-carry renewal.';
const PROVIDER_ADMISSION =
  'A provider attempt is admitted only while its owned operation is reserved. Admission checks the current operation state and assigns its attempt sequence under the operation row lock before provider work begins. If release wins the lock, stale admission is refused without dispatch; if admission wins, release cannot discard the dispatched reservation. Even when a release request started first, an attempt committed before release obtained the operation lock prevents a refund. Concurrent admissions receive distinct sequential attempt numbers. Failure to acquire the owned operation lock refuses admission before creating an attempt. An explicitly requested retry after a failed attempt remains attributable while the reservation is still valid; settled, released and reconciliation-required operations do not admit another attempt. This does not automatically retry provider work.';
const RENEWAL_RETRY =
  'A later verified delivery of the identical paid-renewal event can retry its retained, unprocessed receipt after a recorded failed attempt. If the credit transaction already committed but receipt completion failed, the saved-period guard preserves later spend instead of granting the allocation again. Completed receipts, changed event payloads and unrelated event handlers keep their duplicate protection. A failing concurrent retry cannot replace a successfully processed receipt with failure. This recovery does not automatically repeat provider calls.';
const OVERAGE =
  'When overage billing is configured, Builder accounts with overage enabled are billed $0.04 for each settled credit past their credit allocation. Credits held by an open reservation are not billed until it settles; credits returned by release or partial settlement are not billed, while the portion actually settled can incur overage, and an outcome left reconciliation_required counts as settled. Reporting requires both CREDITS_OVERAGE_METER_ID and a valid explicit UTC CREDIT_OVERAGE_REPORTING_SINCE. Only billing periods starting at or after that activation instant may queue or deliver overage; the period already in progress and earlier retained outbox rows are not backfilled. Missing or invalid activation disables reporting. Within an eligible period, overage is reported once as it settles. Configuring a new meter does not change existing Dodo subscription price snapshots; the configured Builder price applies that meter to new subscriptions. Enterprise and free plans are not billed overage this way.';
const RETRIEVAL_ATTEMPTS =
  'When metadata.retrieval_attempts is returned, preserve its search scope and evidence limitation. An unresolved supplied source or a bounded search with insufficient evidence does not prove that the data does not exist. Official-only restrictions apply to the final publisher after redirects. For numerical claims, match metric, observation period, currency and scale; publication year alone is not the observation period. Keep conflicting official publications distinct until their scope and precision are reconciled.';
const LITERAL_SOURCE_CONTEXT =
  'Retain literal source context without treating proximity or relevance as proof of a metric, observation period or unit. HTML table units can retain standard ISO currency codes, literal currency symbols and explicit nonfinancial Unit: or Units: declarations. Unknown or ambiguous headers, units and periods stay unknown; do not infer a currency from an ambiguous symbol. Native PDF year-table quotations retain a uniquely bound printed heading, caption, unit line and column header as source context, when present. Printed TOTAL rows and their component values remain unchanged. On servers implementing retained-table-consistency/2, source findings add only the literal displayed percentages in one spreadsheet ownership column under a holder header, and never infer a denominator or a corrected allocation. Columns labelled as a change, delta or dilution are not ownership columns, and rows labelled as subtotals are skipped rather than added. Each added percentage keeps its own printed rounding. A sum above 100% beyond that rounding, or a source total above 100% stated as a literal or as a SUM over exactly those cells with no subtotal inside, is a discrepancy. When the rows exceed 100% but a literal stated total of 100% or less disagrees, or when issued holdings share the column with reserved, pool or option rows and the source states neither a fully diluted basis nor such a total, the result stays needs_evidence. A table with more holder rows than one finding can anchor (20 occurrences) is reported as needs_evidence that the table is too large to verify, anchoring the header, first and last holder rows and any stated total. Separate tables are never added together, and a table with a formula or non-percentage ownership row is not summed. Context does not certify the metric or observation period, and a heading is not borrowed across earlier table rows or ambiguous overlapping text.';
const MCP_PROFILES =
  'Local and hosted MCP expose public API tools by default. Set `WEBCITE_MCP_PROFILE=core|docs|research|full` to change local discovery.';
const API_TIMEOUT =
  'Local SDK and self-hosted MCP API requests allow up to 15 minutes (900000 ms) for response headers and body by default. Set `WEBCITE_API_TIMEOUT_MS` to a positive integer of milliseconds to change it; invalid values fall back to the default with a warning.';
const STATED_FX_EVIDENCE =
  'On serving verification releases implementing claim-stated FX comparison, one unambiguous claim-stated equality or unit ratio between ISO currencies can retain auditable conversion arithmetic. The rate is never fetched or assumed; an ambiguous pair quote or conflicting stated rates remains unresolved. Conflicting or missing printed currency/scale declarations cannot supply bare source figures. Existing evidence comparability guards run before stance adjustment. Conversions use only explicitly printed source currency and scale. The arithmetic does not certify the claim or independently promote a citation stance; a rate that cannot establish the proposed support or contradiction leaves that conclusion unresolved.';

const SEARCH_NARRATIVE =
  '`search_sources` search_result text is a model-written summary, not evidence. On serving releases implementing narrative_status, no_sources means no citation was retained and narrative fields are empty except for the legacy NOT_SEARCHABLE sentinel. With model_text, [n] identifies the nth returned citation (or the flattened claim_groups citations when citations is absent). A marker is retained only for a fetched publisher passage containing the figures and literal metric/unit context of its sentence or row, or most words of a figureless sentence. Grounding, fallback and unknown passage provenance cannot bind a marker. This conservative passage binding does not certify the statement; treat unmarked figures as unsourced model text and check the original passage with get_source_preview.';

const VERIFICATION_TIMEOUT =
  'On serving releases implementing the 600-second verification default, CITATION_AGENT_TIMEOUT_MS accepts integer milliseconds from 1 to 2147483647. Missing or blank values use 600000 ms; invalid nonblank values warn and use that default. Reaching the backend ceiling remains a 503 VERIFICATION_TIMEOUT failure. Aborting does not establish a zero charge or a refund. The Redis paid-request lock must last at least the configured agent budget plus 60 seconds. Short verification overrides retain the 300000 ms paid-work lock floor for visual extraction.';
const AGENT_CHECKPOINTS =
  'Keep the public thread_id stable when continuing work with the same authenticated owner. Internal agent checkpoints bind the owner and thread together; sharing a thread_id across accounts does not share agent history. Older unscoped agent checkpoints are not resumed because their owner cannot be established. This does not change saved review IDs, claims or completed receipts. In-memory agent checkpoints do not survive a process restart; use saved job and review receipts to recover completed work. Without MongoDB checkpoint configuration, agents use memory storage. Configured MongoDB connection or checkpoint setup failure prevents new agent startup instead of switching to memory; restoring MongoDB does not move existing in-memory checkpoints into durable storage. If a resumed agent task reports a token-usage storage or identity error, preserve the original thread and inspect saved operation receipts before retrying paid work.';
const DURABLE_API_BASE =
  'For new agent conversations, configure your local SDK or self-hosted MCP server with WEBCITE_API_URL=https://api.webcite.co/durable to use MongoDB agent checkpoints. Keep the same API base, authenticated owner and thread_id for every continuation. Existing conversations keep their original base; changing the base does not move their in-memory checkpoints. Saved review and job records are already durable, separately from these agent checkpoints. The public hosted MCP keeps its existing API base; /durable is an API base, not a hosted MCP connection URL.';
const ASSET_OWNERSHIP =
  'Standalone document searches and mappings require active, undeleted assets owned by the authenticated account. Asset IDs supplied by a model are checked before document retrieval. A missing, inactive or foreign asset fails the ownership check; do not treat that failure as evidence that its document has no relevant content.';
const CONVERSION_ACCOUNTING =
  'Accounting preserves known saved conversion values. Ambiguous legacy zero defaults do not prove free usage. A conversion error does not invalidate saved verification evidence or establish a zero charge. Inspect retained operation receipts before retrying paid work. Previously overwritten conversion values are not restored by this protection.';
const TOKEN_PROJECTIONS =
  'Within an established current billing period, token-usage projections serialize for the same authenticated owner. Replaying a saved citation snapshot does not deduct its token total again; additional saved usage applies only its increment. Known per-citation token-balance adjustments are preserved, and a null token balance stays unknown. Historical, duplicate, unattributed or boundary-ambiguous usage refuses projection rather than guessing. This protection does not change operation-ledger credit receipts. External projected-usage delivery is enabled only by an explicit immutable USAGE_METERING_SINCE activation cutoff and configured meter. Eligible current-period projections commit a pending event with their local balance update; a restart drain retries the same event ID until ingestion is acknowledged. Only then does the acknowledged watermark advance, and any newer increment becomes another pending event. Missing customer or period identity and historical token rows are not initialized as new charges. Events whose original period has expired remain quarantined for reconciliation instead of charging a later period. Meter values retain the legacy projected-unit convention; they are not an additional claim-credit receipt.';
const PROVIDER_RECORDING =
  'Provider recording failures require reconciliation before repeating paid verification. They do not establish source-provider unavailability or a lack of evidence. Keep the saved review ID and operation receipts; previously saved results remain available. If an attempt cannot be recorded, its provider call does not start. Already dispatched work cannot be undone. Completed cache hits create no new provider attempts. Attempt status does not establish billed provider cost; missing historical attempts do not prove that no provider ran.';
const VERIFY_CANCELLATION =
  'When verification observes cancellation before a new tracked provider invocation, it preserves the original reason and does not start that invocation. Work already dispatched may still finish; a recorded attempt may have an unknown outcome and require reconciliation. Cancellation does not establish a zero charge or a refund.';
const REVIEW_READ_CANCELLATION =
  'Cancelling a get_document_review MCP request forwards cancellation to its saved-read HTTP request. Known request credit receipts are retained when JSON parsing fails or a verification stream is missing or incomplete. Missing receipt fields remain unknown. These failures do not confirm a result, a zero charge or a refund; inspect retained operation receipts before repeating paid work.';
const SEARCH_CANCELLATION =
  'A source search cancelled before it starts preserves the original cancellation or deadline reason and does not start that search work. This does not establish that a publisher lacks relevant evidence, undo completed work or confirm a refund; inspect retained receipts before retrying uncertain paid work.';
const TOKEN_USAGE_ACCOUNTING =
  'Account usage lists and totals no longer repeat the sub-prompt rows of a multi-prompt verification once its combined record is saved; legacy grounded sub-prompt records and usage recorded before this change can still appear twice. This does not change credit charges or billing. Multi-prompt verifications saved after the stance-usage fix also record the tokens spent on per-claim stance analysis in their combined usage record; records saved before that fix omit them. If stance usage for any claim cannot be measured, the response reports usage_unknown: true rather than a partial total. Deep-agent sub-prompt stance calls are included in the combined usage record once, including when sub-prompts do not save their own citations. Missing measurements mark the combined usage unknown. Stance and enhanced-analysis receipts retain the provider and model that served the call. Token totals and the legacy token balance fields (consumed, current_balance) therefore rise for these requests; credit charges per request are unchanged. Verifications saved after the verdict-usage fix also record the tokens spent generating verdict explanations, for single-prompt and multi-prompt verifications, and count them in token totals and the legacy balance fields; records saved before that fix omit them. An unmeasured verdict call reports usage_unknown: true. Single-prompt search responses include usages with input_tokens, output_tokens, total_tokens, usage_unknown and cached. These totals include measured search, stance, enhanced analysis, verdict and recovery calls made by this request. A cached replay reports zero request tokens with cached: true. Missing measurements or unconfirmed token saves set usage_unknown: true; do not treat such totals as complete. Recovery receipts keep each serving provider and model separate. The TypeScript VerifyClaimResponse.usages property is optional; older responses without usage stay absent. Credit charges per request are unchanged. Verifications from an account with no billable period (no active, trialing or in-grace cancelled subscription, or a billing period that has already ended) no longer fail on usage accounting. Their token log rows are saved and still count in token totals, but no account usage list row is written and the legacy balance fields (consumed, current_balance) are not updated; these tokens are not backfilled when a new period starts. Credit charges are unchanged. Free plans renew every 30 days: within about 10 minutes of a period ending, a new 30-day period starts with the monthly credits and the legacy balance reset, and no credits are added for missed months. A verification in that gap is skipped this way. A cancelled plan inside its paid period stays billable. A billing period whose end is at or before its start is rejected as corrupt data; its balances are not rewritten. For stance, enhanced analysis and verdict calls, and the combined row of a multi-prompt verification, the request waits up to 5 seconds per save for confirmation that its token log row was written. An unconfirmed save continues in the background; a failed write is retried once. Multi-prompt responses report usage_unknown: true when a save is not confirmed. The legacy balance fields are projected in the background and can lag behind the response. Once the operator has set the reconciliation start date, a reconciliation pass runs every 5 minutes and retries recent saved rows after a 2-minute settling window; startup also scans older rows in batches, never earlier than that date. It only counts fully priced rows inside the current billing period and at or after the configured rollout cutoff. Unpriced, invalid or out-of-period rows are skipped, so reconciliation does not guarantee that every saved row will be counted. Final skip decisions are retained across process restarts with the fingerprint and reason for the rejected rows. A new token row changes the fingerprint and allows another eligibility check; an unchanged rejected set is not repeatedly projected. When durable external metering is activated, eligible rows counted by that pass use the same pending-event queue; projection replay does not create another event for an acknowledged increment. Credit charges are unchanged. Research runs are validated before their root operation opens. A run missing max_tokens or deadline_ms gets a 400, a run that fails another run check is also rejected, and neither leaves a new root. Only document-review credit roots may open without a token cap and a deadline. Roots opened by runs rejected before this change are not removed. Replaying the root_idempotency_key of one that lacks a token cap or deadline, or reusing a key that names a child operation or a root of another kind, is refused with a 409; a capped root is returned unchanged only when its max_credits and max_tokens match the replay. An operation reservation key replayed with another kind, root, credit amount or token amount is also refused with a 409. A root key replayed as a reservation, or a reservation key replayed as a root, is refused with a 409 as well. Use a new key. Streaming verifications without uploaded documents record the tokens spent on search, stance analysis, verdict generation and claim decomposition on the citation they create. When no citation is created, measured calls are saved as unattributed token receipts for the authenticated request owner; they are never attached to an earlier citation. The stream waits for those unattributed receipts to be saved; a failure remains a stream failure. Their result and metadata events carry usages with input_tokens, output_tokens, total_tokens and usage_unknown; usage_unknown: true means at least one model call could not be measured or a token save was not confirmed, so the totals must not be treated as complete, and a cached replay reports zero tokens with cached: true. Credit charges are unchanged. Document-review claim results also carry usages: measured search, stance and judge calls belong to the claim citation, and usage_unknown preserves missing measurements or unconfirmed saves. A saved claim replay retains its original usage summary and does not make another model call or add another receipt. Extraction usage belongs to entity_type document_review and the owned review, not a fabricated claim citation. Durable extraction checkpoints reuse saved responses if writing their usage receipt fails. Reviews from older extraction versions retain their legacy retry behavior: retrying a failed extraction with the same thread and files can make a new model call, and each new successful call attempts to record extraction usage; missing or unconfirmed usage remains unknown. For a fresh older review, a receipt-write failure after successful extraction saves unknown usage before advancing the source cursor and preserves the paid extraction result. A failure to save that marker remains a failure. Older reviews can retry a retained response that fails the extraction JSON or disposition contract. Any recoverable original usage is recorded first under its existing receipt key and occurrence time; newly saved receipts use an available matching rate for that time, and missing measurements stay unknown. A retained response that passes extraction validation is reused without another call. For older reviews, a retained response whose focused table repair still leaves source cells missing is preserved but marked incomplete. The next explicit retry reuses earlier valid responses and retries that failed repair; durable reviews keep their existing fail-closed behavior. A durable failed or dispatching checkpoint without a complete response remains unresolved and is not automatically redispatched. Replayed extraction usage retains its original occurrence time. Newly saved receipts use an available matching rate for that time, never the replay time. Existing receipts retain their saved pricing without backfill, so an existing unpriced receipt remains unknown even if a matching rate is now available. Newly saved receipts without a matching rate stay unpriced and extraction usage stays unknown; older checkpoints without the original time remain unknown. A different review reusing an extraction cache does not inherit the original paid call as new usage. These token records do not change operation-ledger credit charges.';

const BILLING_POINTER =
  'Billing, plan renewal, overage, rate limits, accounting, token usage and agent checkpoints: call `webcite_guide` with `{ "workflow": "billing" }` (0 credits).';

const BILLING_REFERENCE = [
  EMAIL_OTP_DELIVERY,
  BOT_RATE_LIMIT,
  FREE_RENEWAL,
  PAID_RENEWAL,
  HISTORICAL_REFUNDS,
  PROVIDER_ADMISSION,
  RENEWAL_RETRY,
  OVERAGE,
  RETRIEVAL_ATTEMPTS,
  LITERAL_SOURCE_CONTEXT,
  MCP_PROFILES,
  API_TIMEOUT,
  VERIFICATION_TIMEOUT,
  AGENT_CHECKPOINTS,
  DURABLE_API_BASE,
  ASSET_OWNERSHIP,
  CONVERSION_ACCOUNTING,
  TOKEN_USAGE_ACCOUNTING,
  TOKEN_PROJECTIONS,
  PROVIDER_RECORDING,
  VERIFY_CANCELLATION,
  REVIEW_READ_CANCELLATION,
  SEARCH_CANCELLATION,
];

function withReference(header: string, steps: string[], reference: string[]): string {
  return header + [...steps, '', '## Reference for this workflow', ...reference, '', BILLING_POINTER].join('\n');
}

export function renderWebciteGuide(input: {
  workflow?: unknown;
  question?: unknown;
}): string {
  const workflow = resolveGuideWorkflow(input.workflow);
  const question =
    typeof input.question === 'string' && input.question.trim()
      ? input.question.trim()
      : undefined;

  const header = [
    '# Webcite guide',
    '',
    'Free plan: **100 credits/month**. This tool costs **0 credits**.',
    ...(question ? [`Your question: ${question}`] : []),
    '',
    '',
  ].join('\n');

  if (workflow === 'quick_verify') {
    return withReference(
      header,
      [
        '## Workflow: quick_verify',
        '1. Call `verify_claim` with:',
        '```json',
        JSON.stringify(
          {
            claim: question ?? 'The Eiffel Tower is 330 meters tall',
            include_stance: true,
            include_verdict: true,
          },
          null,
          2,
        ),
        '```',
        '2. Optional: `get_source_preview` on a citation URL/quote to show bind-back.',
        'Credits: typically 2–4 for verify_claim.',
        'Cancelling a verify_claim_stream MCP request forwards cancellation to its backend HTTP request. A stopped or failed stream requests cancellation of its unfinished response body. Partial events do not confirm a result without a done marker. Cancellation does not establish completion, rollback or a credit refund; inspect saved operation receipts before retrying uncertain paid work.',
      ],
      [RETRIEVAL_ATTEMPTS, PROVIDER_RECORDING, VERIFY_CANCELLATION, VERIFICATION_TIMEOUT, STATED_FX_EVIDENCE],
    );
  }

  if (workflow === 'document_quote') {
    return withReference(
      header,
      [
        '## Workflow: document_quote',
        '1. Use the existing Webcite asset_id when available. For a Claude chat attachment or a file above the hosted tool limit, upload the original binary in Webcite Playground or through authenticated HTTP multipart/resumable upload within the parser\'s format and size limits. Use the returned asset_id. If the upload returns parse_job_id, wait for parsing; if it returns parse_required, call parse_endpoint. The remote MCP server cannot read a local path or automatically access a chat attachment. If the original file has a public HTTPS URL, use upload_url instead: the server fetches bounded original bytes through public-address and redirect checks and returns owned asset_id, asset_url and source_version_id. Save those references; upload costs 1 credit, and successful storage does not prove completed parsing or a full review. Use `upload_file` only for small files when the client directly supplies original bytes as base64; never reconstruct bytes from extracted text.',
        '2. `extract_document` on the uploaded asset',
        '3. `get_source_preview` with the quote and asset_id / versioned ids',
        'Quote binding does not treat an en dash, em dash or minus sign as a hyphen: a quote of 2023-24 does not match source text printed as 2023–24, exactly or after normalization, so it binds at best as fuzzy; copy the source\'s dash character into the quote.',
        '4. Optional: `verify_batch` for many quotes',
        '',
        'Do **not** invent URLs.',
      ],
      [ASSET_OWNERSHIP],
    );
  }

  if (workflow === 'document_review') {
    return withReference(
      header,
      [
        '## Workflow: document_review',
        '1. If the file is already in Webcite, use its asset_id. Hosted MCP uses stateless authenticated POST requests; missing or obsolete mcp-session-id headers do not block tools. Backend job_id and review_id preserve workflow progress across reconnects. No balance preflight is required: use inline credit_usage from normal responses, and get_credit_balance only for an explicit balance question or unresolved credit refusal. Missing receipt fields remain unknown. For a Claude chat attachment or a file above the hosted tool limit, upload the original binary in Webcite Playground or through authenticated HTTP multipart/resumable upload within the parser\'s format and size limits. Use the returned asset_id; the remote MCP server cannot read a local path or automatically access the attachment. For an original file at a public HTTPS URL, upload_url fetches up to 100 MB with a 30-second budget, checks every redirect and DNS address, forwards no caller credentials, and returns owned asset_id, asset_url and source_version_id. Use those saved references, not a reconstructed binary; upload costs 1 credit only on successful storage, and uncertain failures require receipt inspection before retry. If completion returns parse_job_id, wait for parsing; if it returns parse_required, call parse_endpoint. Use `upload_file` only when the client directly supplies original bytes for a small file, never reconstructed document text. Save the asset_id and source_version_id from upload. For a full review, proceed directly to review_document: the server reads the stored representation and waits for parsing when needed. Do not pay for extract_document merely as a review prerequisite. Use extract_document only when the user also needs extracted content or a specific source-read anomaly requires inspection; its per-call charge can apply even when stored OCR is reused. Never call a partial read complete.',
        'Optional source inspection: some connectors show only MCP text and omit structuredContent. Extraction text is bounded at 16,000 characters and lists links beyond that limit. An asset_id is not a source_version_id. Use get_latest_representation and read_source_unit for complete stored units when needed; extract_pages costs 1 credit per call. Repeating `extract_document` or `extract_figures` incurs the stated per-call credits. These are anomaly/content inspection tools, not mandatory review preflights.',
        'For a JPEG/PNG whose retained text lacks layout evidence, explicitly opt in with extract_document visual_rendition:true, the owned asset_id, exact source_version_id and an explicit idempotency_key. This operation costs 1 account credit; preserve its key and receipts on failure, never automatically start another paid attempt. A model reply that is not valid JSON or breaks the output schema is kept but never replayed: the server calls the model once more with the same input, charges the credit only for an accepted reading, and settles a request that ends with invalid output at zero credits. If the second reply is also invalid, the request fails with retryable HTTP 502 model_output_invalid; a new key dispatches a fresh attempt. Retrying the same key returns that error again until another key has produced a valid reading for the same source; it then returns that reading with credits_used 0, because it was paid under the other key, and its own operation stays settled at zero. After three invalid attempts for the same source and policy it fails with HTTP 422 model_output_invalid_exhausted, marked retryable: false, and repeating it cannot succeed. It returns a separate model-generated partial representation without changing the selected review source. Use the returned source_units IDs with read_source_unit to inspect its stored visual evidence, then inspect the exact saved gap with get_review_source_span, whose role may remain unknown. An explicit record_review_nonclaim action can reference visual_evidence representation_id and unit_key; the server rechecks source bytes, literal offsets and geometry. Whole-label bold or italic formatting can match the same plain-text label while preserving its wording. Layout roles do not prove nonclaim, agent actions do not imply analyst approval, and factual/numeric headings remain gaps. Only an isolated source-bound page footer can support a numeric nonclaim. Eligible inactive failed residual reviews reconcile complete retained extraction responses without new generation or rewriting saved claims; missing, incomplete or ambiguous evidence refuses. Partial source reads stay partial even when these gaps are accounted for.',
        '2. Call `review_document` with a clear prompt, asset_ids and a stable thread_id. Pass official PDF URLs supplied by the user or found with `search_sources` in source_urls, with the required source filters. Save its job_id. There is no fixed claim count. The server checks claims in the background and saves each completed result. When an account-credit spending limit is required, pass max_account_credits as a positive integer. Each checked claim reserves its credits against that limit before any provider call, so a capped review stops checking claims once the limit is reached. It caps new charges plus outstanding holds for that execution; historical completed claims are not charged again. The cap is immutable for the same job/idempotency key, including omission after a capped submission. A later explicit retry execution has its own budget: pass its authorized cap explicitly. Omission requests no execution cap. This does not bound provider calls or provider currency cost, and it does not guarantee full coverage. If the response fails to confirm the requested cap, enforcement is unknown: inspect the existing job and do not resubmit automatically.',
        '3. Inspect the saved claim list and source coverage for every material figure, period, comparison and relationship in all readable pages/sheets. Do not infer full source coverage when coverage_complete or source_read_complete is missing or false. `extract_figures` can add recognized financial metrics, but zero results does not mean there are no numbers. Check omitted claims individually with `verify_claim` using distinct stable idempotency keys. Report an official PDF read failure instead of substituting secondary sources. Evidence must address the same metric, period, unit and geography. A candidate that cannot be grounded in the source does not stop the review: it is listed in rejected_claims with its reason and, when the model supplied them, its source_quote and source_fragments, the remaining claims are still checked and charged per claim, and the job ends partial_coverage with coverage_complete false.',
        '4. Poll `get_document_review_job` with job_id at zero credits, waiting about 30 seconds between checks. A review_id can appear before work finishes. Unless the user requests interim results, wait for a terminal job status before reading result pages, then call `get_document_review` to read saved checked and pending claims, source coverage, uncovered spans, rejected candidates and explicit nonclaim dispositions. Copy the returned next_page_input exactly for each next call, including exhausted-stream offsets, until it is null. Do not reset exhausted offsets to zero. The individual next_offset, next_gap_offset, next_rejected_offset and next_disposition_offset remain available. For a source-attested heading, table title or navigation gap, read its exact text with `get_review_source_span`; record a nonclaim with `record_review_nonclaim` only after assessing the entire passage and giving a rationale that it contains no factual assertion. Structural role alone never closes a gap. Leave any assertion-bearing passage uncovered. For the final report, use the saved claim outcomes, verdict summaries and citation URLs on these pages. A compact view can omit detailed evidence; omission from the view does not mean it was never saved. Compact fields omitted are unknown, not absent. Report known material_claims (physical rows excluding duplicates), total_claims (all physical rows), duplicate_claims and non_factual_claims separately. Material counts can include non-factual rows and do not imply all rows are factual assertions. A duplicate display alias can have a different id; original_claim_id is its stored original identity and duplicate_of_id identifies the canonical assertion. Display aliases do not change stored IDs, citations or paid operations. Report pending, failed, rejected and uncovered counts separately. pending_claims is unfinished work and includes failed_claims; failed is a subset, never add it again to a total. Counts do not establish attempt history; do not call other unfinished rows never attempted without recorded attempt data. A provider access error does not rule out incomplete extraction or source coverage. Null or missing counts are unknown, never zero. Do not group unknown rejected or uncovered counts with known zero pending or failed counts. A completed job means processing finished; it does not prove complete source coverage. For a queued or running review, obey poll_after_ms with waits of at most 30 seconds. Never multiply remaining claims by per-claim latency into a long blind sleep. Stop polling immediately on a terminal status and report failed or interrupted work. Do not infer source weighting, prioritization or analysis absence from omissions. Fetch verbose evidence details only when that specific audit requires them, not routinely. A null summary is unknown and a summary_truncated flag means the complete saved summary was not displayed. Use source titles as link labels and complete returned URLs as link targets; never replace URL paths with ellipses. Extra citation/source-unit endpoints are needed only for requested evidence details or a specific anomaly. Inspect those citations with `get_source_preview`; `verify_batch` checks quote binding, not claim truth.',
        '5. If credits run out or the job fails, give the user the saved checked claims, unchecked claims, and uncovered source passages now. After credits are available or the failure is diagnosed, call `review_document` with the same prompt, thread_id, assets, source URLs, filters and billing flags plus retry_failed: true and the returned retry_idempotency_key. Keep the original thread and file. The failed job receipt is retained; completed claims replay without a new charge. A failed or interrupted execution releases only its own inner review lease for prompt explicit retry, preserves saved outputs, and leaves foreign, newer or terminal leases unchanged. Completed extraction responses are also reused when the source, extraction request and model settings are unchanged. A failed or incomplete extraction response is not reused as a successful result. Do not repeat separate `verify_claim` calls that already completed. A resumed review reuses saved extraction: a chunk whose extraction already completed is not sent to the model again, and extraction itself is never charged.',
        '6. To apply the current evidence policy to a settled claim, read its original_result_hash and call `revise_document_claim_analysis` after the review stops. This reuses saved snippets without new research, model calls or credits. The original result and receipt remain in revision history. A missing scope assessment stays inconclusive; this operation does not promise fresh semantic analysis.',
        'Saved-review continuation covers claims, uncovered passages, rejected candidates and nonclaim dispositions separately. The SDK rejects a returned cursor that repeats, skips or contradicts its saved page boundary instead of inventing a replacement. Copy a valid next_page_input exactly, including exhausted streams. An absent cursor while stream totals are pending or unknown does not establish exhaustion or complete coverage. A pagination contract error is not a reason to start another chargeable review; inspect the retained page and API response.',
        'Credits: optional extraction costs 1; document review charges per claim. Upload responses retain available credit_usage in both text and structured output; a missing upload receipt means unknown charge, never zero. credit_usage describes this HTTP request; review_usage describes accumulated operation-ledger charges, not polling costs. Balance and saved-review readback cost 0.',
        '',
        '### Extraction and evidence notes',
        'Canonical binary upload reuses one structured OCR pass for raster content and preserves partial reads and errors. OCR rasterization bounds each page image\'s long edge so large image-only slide PDFs remain readable within the analysis budget; unreadable raster regions remain partial. Native PDF coordinates preserve table year/value bindings. PPTX native rendering retains the slide inventory, including unreadable slides. Native-only source reads do not establish complete raster coverage. Ordinary text OCR does not provide bounding boxes or certification; inspect the original for exact visual placement and unresolved content.',
        'On a server with source-backed media transcription support, enabling CONTEXT_GRAPH_ASR requires an explicit ASR_MODEL, Vertex project and location, and an available shared paid-request cache. Inline media is limited to 14 MiB and requires a positive decoded duration. Recognized phrases retain timed source locators and tenant, source, content, model, prompt and settings identity. Speech text and timestamps are model-derived, unreviewed recognition, not certified complete source coverage. A raw response is cached before usage and transcript validation; incomplete responses, unknown usage and missing retained responses remain failures rather than empty success or automatic paid retries. Replayed usage keeps the original receipt identity and occurrence time, without inventing historical prices. A validated cached ASR response can reuse its owned, already settled zero-credit operation, including after a concurrent completion. This reuse does not admit unresolved outcomes or nonzero-credit completions; infrastructure failures remain failures. Deterministic intake remains metadata-only.',
        'Extraction preserves retained source units\' partial, unreadable and error states and their OCR method across PDF and PowerPoint, including image-only slides. A mixed full-scope review includes narrative assertions and scope qualifications as well as numbers; numerical extraction alone does not complete it. Bind HTML table numbers to exact original cells and headers, including uniquely matched footer years. Do not flatten table cells into prose or guess ambiguous years; leave unresolved bindings as source gaps. Partial or unknown coverage remains explicit and does not certify the source.',
        'For a numbered heading with ordered actions, keep the complete literal action sequence and its exact numbered source passage. Identical action wording at separate numbered locations is distinct evidence; do not merge it by text alone.',
        'Split independently checkable facts using ordered literal source_fragments and the complete source passage. Keep shared conditions, qualifications and negation on each applicable claim. A composed source_quote can be anchored back to one uniquely matching literal source unit; the claim must still pass wording and scope checks. Ambiguous anchors or invented wording remain rejected.',
        'A uniquely grounded literal title topic may guide document-review searches and publisher passage selection without changing the assessed assertion. Ambiguous, conflicting or unsupported topics are not inherited from model-written context. Retrieval context remains separate from factual verification: it does not resolve a source gap, certify a partial reading or revise an existing paid result. Passage selection remains bounded by the reader and cannot establish that omitted evidence is absent.',
        'Supplied URLs and discovered publisher pages share bounded semantic passage selection. Relevant evidence may use different wording from the claim. Selection preserves the quoted passage and its page or adjacent context; it does not itself establish support. Unread content, omitted candidates and pages beyond the read or selection budget remain explicit for each source. A failed or timed-out selection, or a PDF with no readable text, leaves that source unread rather than checked without relevant evidence: a discovered page keeps its discovery snippet, marked extraction_failed with no fetched evidence, and a supplied URL is rejected and yields no citation. Results from other sources are kept; a provider recording failure or a cancellation still stops the whole request. A selection that failed before the provider responded can be retried; a retained response that could not be resolved is never regenerated and stays unresolved.',
        'Structural topic headings and connectors between retained literal clauses do not become extra claims; omitted qualifications remain coverage gaps. Source evidence and successful judgments retain their server-verified identity across response projection and cache replay for the exact claim. A copied or changed receipt cannot supply that identity.',
        'Document-review result rows and claim-verification-result events may include source_assessment (version: 1). Its claim is the assessed assertion; the outer claim and claim_id retain the original report description and identity. judgment_claim preserves the exact stance identity with separately marked interpretation context, which adds no claims. basis is original_claim or source_table; optional source_asset_id and source_quote_hash reference retained source evidence; a hash alone does not establish claim truth. Missing metadata on older saved rows is unknown, never proof of a factual projection or a reason to rerun settled work. A policy-only revision reuses the saved assessment identity; changing its predicate requires fresh analysis.',
        'Literal Unicode table labels remain anchored to the original source cells and headers; recognizing a label does not translate it or supply missing metric, year, value or unit proof. Numeric-only labels and unresolved bindings remain unknown. A short source label alone does not establish that external retrieval found readable evidence for its assessed assertion.',
        'Compact saved-review pages retain optional source_assessment_summary separately from the original report claim. Normal assessed assertions and their basis remain available; claim_truncated and judgment_claim_truncated explicitly mark shortened text. A summary is not the exact saved stance identity and must not supply a new judgment or cache attestation. The full source_assessment remains saved; absent legacy metadata stays unknown.',
        'Input source coverage describes the uploaded report, separately from publisher reader coverage on its citations. A verified claim or complete input review does not establish a complete publisher read. Saved review text and compact citation_reader_coverage qualifiers preserve explicit partial reads; missing, legacy or unrecognized publisher coverage stays unknown. citation_index is the one-based position in the saved citation list. Limitation details are bounded, with omitted counts and text truncation marked; full saved evidence remains available. These qualifiers do not change verdicts, confidence or source_assessment identity. Verification stream cancellation still leaves incomplete results and credit outcomes unconfirmed; inspect retained receipts before retrying.',
        'When parsing omits list numbers, literal inline heading boundaries still distinguish headings from their factual body. Structural choice headings are not facts; procedural requirements, action ordering and shared conditions remain part of the review.',
        'Extraction retries identify the same grounded assertion when its literal source quote changes from heading plus body to body alone, preserving the first stored claim instead of appending a second claim to check. Separate source occurrences, assets and page identities remain distinct. Verification runs at most three funded claim tasks at once, bounded by available credits and the remaining consecutive-failure budget; completed results remain saved if another task fails.',
      ],
      [
        RETRIEVAL_ATTEMPTS,
        LITERAL_SOURCE_CONTEXT,
        ASSET_OWNERSHIP,
        PROVIDER_RECORDING,
        VERIFY_CANCELLATION,
        REVIEW_READ_CANCELLATION,
        SEARCH_CANCELLATION,
      ],
    );
  }

  if (workflow === 'source_trace') {
    return withReference(
      header,
      [
        '## Workflow: source_trace',
        '1. Call `extract_document` on the uploaded screenshot or slide. Read the actual table labels, units, years and distinctive figures. If extraction is incomplete, say which part is unreadable.',
        '2. Call `search_sources` with those exact details. If results are secondary or empty, refine the search using a likely regulator or report title suggested by the table. Do not treat a domain filter returning zero as proof that the official source does not exist.',
        '3. Open candidate URLs with `get_source_preview`. Identify the original publisher and page only when the same metric, period, unit, geography and table values are present. For a claim check, pass confirmed official PDFs to `verify_claim` in `source_urls`.',
        '4. If the original source or country is not established by the document and checked URLs, report it as unresolved. Do not infer a country from currency alone or cite a news summary as the original publication.',
        '`ask_document` checks numerical answers inside supplied text; it does not discover external source URLs.',
      ],
      [RETRIEVAL_ATTEMPTS, LITERAL_SOURCE_CONTEXT, ASSET_OWNERSHIP, SEARCH_CANCELLATION, SEARCH_NARRATIVE],
    );
  }

  if (workflow === 'numeric') {
    return withReference(
      header,
      [
        '## Workflow: numeric',
        '1. `extract_document` to read every page and identify its file format. `extract_figures` only finds recognized metrics; zero metrics does not mean the page has no numbers.',
        '2. Use `analyze_document` for PDF, spreadsheet or JPEG/PNG/WebP numeric analysis. Image figures are OCR/model reads and need source review. For a whole-slide external fact-check, also use `review_document`; use `analyze_conflicts` only when you have figures to compare.',
        '```json',
        JSON.stringify(
          {
            asset_id: 'asset_...',
          },
          null,
          2,
        ),
        '```',
        '',
        '### Numeric evidence notes',
        'For a selected original spreadsheet cell, retain its sheet and address, literal display and number format, and nearby labels. A cell that retains more than one numeric lexeme keeps each distinct reading; unresolved parenthetical accounting signs are withheld rather than published as absent values. A source-only cell reading is not an approved Figure or a recalculated formula result.',
        'On development servers implementing selected-source-automatic/8, an explicit Unit, Units or Currency column can bind supported currency and scale from the same spreadsheet row to a numeric reading. Arbitrary notes cannot supply that meaning, and conflicting declarations remain unknown. Formula caches remain unverified. Validated retained engine7 manifests remain readable without regeneration, including compatible read-only requests and exact pinned historical selections; new engine8 deterministic readings can reuse an unchanged model-engine2 request cache. This development rollout does not imply that a production server implements engine8.',
        'On servers implementing selected-source-automatic/10, a spreadsheet cell is dated from the nearest unique period rung (column header, then row labels, then sheet banners), never from the union of every date on the sheet. Two dates at the same rung stay unknown. As-of and diligence banners apply only in header rows; a Notes-column as-of on another row is not a workbook period. Dash-separated sheet titles can name the reporting entity; a colon metric label is not an entity. Compatible empty-body reads remain engine7; retained engine9 manifests are readable only by their exact pin. This does not imply that a production server implements engine10 until that engine is deployed.',
        'On servers implementing selected-source-automatic/11, page-native OCR clues strip a leading slide number and treat a Confidential | Qn YYYY stamp as that quarter-end month so it can compare with a December as-of. A per-month price on the same page does not wipe the stamp, a Confidential pipe title is not a reporting entity, and a bare quarter token from that stamp is not a second competing period. A column header that only says Q4 2026 remains 2026-Q4. Compatible empty-body reads remain engine7; retained engine10 manifests are readable only by their exact pin. This does not imply that a production server implements engine11 until that engine is deployed.',
        'On servers implementing selected-source-automatic/12, a model quote that reproduces a native PDF table row from its printed label cell through the value cell (for example NRR 119% 121%) binds that exact cell, so its period comes from the column header rather than from competing page clues. The value must occur once in the row and exactly one row on the page may match; a quote that skips the label, starts at an unlabeled row, omits the value or repeats across rows stays unbound. Compatible empty-body reads remain engine7; retained engine11 manifests are readable only by their exact pin. This does not imply that a production server implements engine12 until that engine is deployed.',
        'On servers implementing selected-source-automatic/13, an automatic metric definition may declare periodClass flow, point_in_time or static, and every automatic figure scope carries periodStatus: stated when the source gives a period (a stated period wins over a static class, for example SAM FY2030), not_applicable only when the metric is static and the source gives no period, and missing otherwise; a metric without periodClass is treated as flow. A missing period is never filled from a default. Compatible empty-body reads remain engine7; retained engine12 manifests are readable only by their exact pin. This does not imply that a production server implements engine13 until that engine is deployed.',
        'On servers implementing selected-source-automatic/13, periodClass never changes the provider call, its billing authorization or its cost: re-running Analyze after a DD adds periodClass replays the earlier operation without a new charge.',
        'On servers implementing selected-source-automatic/13, a PDF page date applies to a value as a page banner only when the page prints one year and at most one quarter or half label. On a multi-year slide (for example 2024A, 2025A, 2026E and 2027E column headers or chart axis labels) a value takes its period only from a bound table column header; otherwise scope.period stays null rather than taking the first printed year. A header or axis line printing several years, including suffixed years such as 2024A 2025A or FY2023 FY2024, is never read as one period. This page-period rule ships with the engine13 bump that adds periodStatus and does not change engine12 output. This does not imply that a production server implements engine13 until that engine is deployed.',
        'On servers implementing selected-source-automatic/14, a quote whose page text prints the value inside markdown emphasis markers (paired ** or __, for example **$6.2B**) still binds when the quote matches the page text with those markers removed and the bound page span is exactly the value; a span that would include a marker or any other text stays unbound. Compatible empty-body reads remain engine7; retained engine13 manifests are readable only by their exact pin. This does not imply that a production server implements engine14 until that engine is deployed.',
        'On servers implementing selected-source-automatic/15, an automatic PDF quote and its page text are compared in one literal canonical form: whitespace runs, line breaks and NBSP become one space; en dash, em dash and minus sign become a hyphen; smart quotes become straight quotes; a word wrapped with a hyphen at a line end is joined and soft hyphens are dropped; a balanced ** or __ emphasis pair that opens and closes at word boundaries on one line is dropped; and at the start of a page line a heading marker, or a list or blockquote marker not followed by a number, is dropped. A quote such as Serviceable Addressable Market (SAM) $6.2B therefore binds a page that prints a ### heading above **$6.2B**. The quote is canonicalized both as starting mid-line and as starting a line, so a copied 1. or - marker still matches; across both forms the value must land on exactly one page position, and a quote the page prints as is more than once stays unbound. A quote that becomes ambiguous only after normalization is deliberately left unbound, and its reading is still kept as physical_source_only. The bound span is the whole printed numeric token and the reading keeps that printed text as its raw lexeme; the token must state the same value and currency as value_raw, so a page printing US$5bn binds value_raw $5bn, USD 5bn or 5bn USD and stores US$5bn. A sign (minus, en dash, figure dash, fullwidth minus), thousands and decimal separators, a scale from one scale table (k, m, mn, mln, MM, bn, bln, mld, Mds, Mrd, million, billion, Bio. as 10^12, Tsd., lakh, crore and others) or a percent after at most one run of spaces on the same line, an attached multiple, a lower-case bp or bps, and a currency mark before or after the number belong to the token. Two numbers joined by a dash (5-6%, 5%-6%, 5%–6%, $5-6m, $5bn-$6bn) form one range token: neither part binds alone and the second part is never read as negative. So 5 never binds out of 15%, −5%, 5,000, $5,000m, 5 bn, $5MM, ₹5 crore, 5 mln zł or **5**%, while value_raw −5%, 15%, $5 bn, $5MM or 5 mln zł binds the whole print. A letter run touching the number that the tables do not know (5G, 2024A), the size-ambiguous $5 mil, and a spaced capital K, M, B or T without money (5 M users) block the bare number; a spaced lower-case unit letter (5 m, 5 mm, 5 t) or 5 T-shirts is prose. Currency marks resolve through one table of pinned ISO 4217 codes and symbols: $, US$, USD and 5bn USD are USD; A$, C$, HK$, NZ$, S$ and R$ are their own currencies and never bind a bare $ or USD; E£, LE and ج.م are EGP; €, ₩, zł and similar each name one code. A code that is also a common word or acronym (AMD, CAD, PHP, TMT, SAR, COP and others) is a currency beside a number only when the number has a scale or decimals (CAD 5m, not PHP 8 or COP28), and in a heading or label only inside a currency clause such as (CAD m) or Amounts in CAD, never as a bare word. Declarations such as Currency: AUD, All figures in A$m, AUD in millions, Revenue (A$m), US$ thousands and €000 are read for the document and for the page, and the nearer one decides a bare $ or £: a dollar or pound currency settles it, another currency or two conflicting declarations in that scope leave it unknown, and only a document with no declaration at all reads $ as USD and £ as GBP. ¥, kr and Rs stay unknown without a declaration. An Excel format names its own currency through its locale ([$$-C09] is AUD, [$$-1009] is CAD), which wins over declarations; an unknown locale leaves the currency unknown. A bound figure takes the currency its own printed value resolves to (US$5bn in US$5bn (A$7.6bn) is USD); an unresolved mark leaves it unknown, and a value printed without a mark takes a label clause or the nearest declaration. Table cells use the same check. An unmatched marker, an exponent such as 2**3, identifiers such as MAX__CAP or __init__ and a value split by markup are printed text, so a quote that omits them stays unbound. A list marker before a number (- 5%) is kept as printed text, so the quote Churn 5% does not bind ### Churn above - 5%. A quote that reproduces a native table row is compared cell by cell in the same form, including a value cell printed inside one balanced emphasis pair, and its hit is stored as quoteBinding native_table_cell with readingKind native_literal and nativeStart and nativeEnd on the exact value; engine14 stored the same hit as physical_source_only, which looked the same as a miss. A client that validates quoteBinding as a closed list must accept native_table_cell before it reads engine15 results. The model identity is unchanged, so engine15 replays cached provider responses without a new paid call. Compatible empty-body reads remain engine7; retained engine14 manifests are readable only by their exact pin. This does not imply that a production server implements engine15 until that engine is deployed.',
        'Retain formula presence and available formula text or metadata even for self-closing formula nodes or shared-formula followers with no local text. An absent or whitespace-only cached value is absent; a literal cached zero is present. A cached formula value marked present_unverified remains unresolved. Spreadsheet parsing and native source construction do not verify or recalculate formulas and are not calculation authority. On servers implementing the formula-locator repair, source locators preserve non-padded formula text up to 8,192 characters; longer, empty or padded values are refused, and partial source outcomes stay partial.',
        'Use scope.period only for the exact source-supported period. Preserve an analyst literal opaque or partial label, such as an eight-month period, without reconstructing annual boundaries. effectiveTime: null means the effective interval is unknown; it does not establish a full year. Period, actual versus forecast basis and comparable metric meaning still require original source evidence before review.',
        'Product graph lookup binds only when supplied ClaimScope fields (entity, period, unit, currency, scale, basis, definition) match retained nodes; a missing exact scope stays insufficient rather than a nearest neighbour. Retrieval keeps a scaled currency magnitude contiguous so a written figure is not judged as a residue of itself. A passage query may quote one unique source quantity, including a unit-header scale such as thousands, as citedFigure; mixed quantities stay uncompiled, and passage selection never synthesizes that figure. When a Plan/Actual table binds the Actual cell for the claimed metric, a plan limit stated directly for that metric in the same source (for example at or below $400k) does not compete with it, unless the question asks for the plan or limit itself; any other reported figure in prose, or a figure from another source, keeps the quantities mixed. A lookup question that names a measure absent from authorized vocabulary stays unknown_metric; a period token must not bind a neighbour figure. Alias mentions of one party collapse to a single typed node with stated or inferred typing provenance; when no party resolves the answer stays cold-silent. Number, unit header and footnote evidence are cited jointly when all three are present. A private-room contradiction without an explanation from that same source does not stand as a contradiction.',
        'In the dedicated DD host workflow, signed selected model and Figure inputs retain evidence.entityId, rawLexeme, displayLexeme, numberFormat, scopeEvidence and effectiveTime from the selected occurrence and reviewed interpretation. The input manifest binds this evidence; the existing assertion identity is unchanged. Preserve the literal raw reading separately from valueDecimal and carry unknown intervals as null. These inputs are not public MCP tools and do not approve a report Figure or verify a formula cache.',
        'On development DD integrations implementing lossless model-evaluation receipts, the retained evaluation preserves exact finite computed values and their hashes through JSON storage. New versioned receipts preserve earlier records; valid legacy receipts remain readable, while corrupt legacy payloads remain refused. This storage repair does not round model values, certify source readings or grant analyst approval. It does not imply that a production server implements this receipt format.',
        'If a selected input contains semanticScope.measurement or signed evidence.measurement, preserve each optional fact and its exact source clue: retention horizonMonths, cohort and ratioMeaning; workforce basis and geography; ACV basis, cohort and contractId; and costConvention. Supplemental facts require proof from the retained selected source; they may fill missing facts without changing assertion identity, review identity or semantic role. Conflicting explicit and supplemental facts must fail visibly, never overwrite the reviewed meaning. Omission means unknown and preserves the existing reading. A cost formulaWitness establishes only the source expense convention from its retained P&L labels and formulas, never the correctness of cached results. These source facts require no new DD screen, review workflow or generation gate; support for the optional fields alone does not prove automatic extraction supplies them.',
        'For a validated registered NRR conversion, retain the signed source value and unit separately from the DD target value and unit. Source ratio 1.18 displayed 118% maps to target 118 percent without rewriting source identity. A source multiple requires explicit NRR ratio meaning; an unrelated valuation multiple is not convertible. Existing answers and citations must use the target unit for presentation and the exact retained source lexeme for citation validation. Unknown retention horizon or cohort remains unknown after conversion.',
        'Compare only the same metric meaning, entity, measurement scope, period, interval, actual or forecast basis, role, unit and currency. A shared numeric unit or generic definition does not make Net New ARR and Ending ARR, FTE and total headcount, contract and blended ACV, or Gross Margin and retention comparable. Missing retention horizon, cohort, workforce basis, contract scope or cost convention needs evidence; do not infer it from a default or a signed number. Ratio, percent and multiple representations need an explicit metric-specific conversion contract; do not coerce unrelated multiples or negate expenses automatically.',
        'For automatic extraction in an existing DD analysis, consume only results bound to the current selected source, receipt, source units, engine and metric configuration. This private backend handoff is separate from analyst-approved mappings and adds no public MCP tool or DD review prerequisite. Preserve source raw and display readings, source-supported canonical meanings, exact clues, extraction method, uncertainty, physical and semantic coverage, and operation usage. A present formula cache may be an unverified source reading requiring review; an absent cache is unknown, never zero. Extraction confidence does not verify arithmetic or establish analyst approval.',
        'In a DD host, retained source findings for a selected workbook can also include deterministic needs_evidence questions read from one source\'s retained cells with no model call: a full-year SUM or AVERAGE whose range covers fewer monthly periods than a year, or than same-grained sibling year totals, and either stops before the year end (the last month of a 12-month sibling year total; without one, December, or the range\'s own last month when it crosses December with no month column printed after it) or starts after the year\'s first month with a month column printed just before it, citing the exact cell, formula range and header (labels that name a partial period or a month range shorter than a year, with or without years, are excluded, as is a forecast year such as 2026E or FY26E whose range has no month column printed directly before or after it, a model horizon; a range naming all twelve months, or running through December, is a full-year label; a leading stub year that starts mid-year with no earlier month printed and runs to the year end is not questioned); and a printed gross margin percent that the same column\'s revenue and COGS cannot produce within the printed rounding of all three, reading COGS as a magnitude. Neither is a corrected value or a recalculation of the workbook. A result retained before these checks is reinterpreted from its accepted paid stages on the next authorized Analyze without a new provider dispatch or credit hold; until then a read-only current read reports it missing, and its exact manifest stays readable. On servers implementing source-finding-kind/1, each source finding can carry an optional `kind` naming its check (`source_comparison`, `table_range_average`, `table_ranked_concentration`, `cap_ownership`, `workbook_annual_sum` or `workbook_gross_margin`), and a `cap_ownership` finding also carries `capOwnership` with `holderRange`, `totalCell` (null without a stated total) and `summedPercent`; read these fields rather than parsing description or limitation wording, and treat a finding without `kind` as retained before the field.',
        'Comparison dimensions apply across configured metrics, including custom metrics. Preserve independently evidenced axis and member meanings for population, product, channel, geography, denominator, contract or other source dimensions, alongside entity, period, interval, basis, role, unit and currency. Keep the exact supporting caption or span separate from the qualifier value, so surrounding metric values do not become scope identity. Different axis order does not imply different scope; contradictory or unsupported dimensions remain uncertain. Special retention, workforce and ACV fields are compatibility facts, not a complete list of possible qualifiers. Do not treat arbitrary wording as an alias, discard dimensions or infer a company total from a scoped row.',
        'In a host product that offers contextual numeric review, a human reviewer may explicitly mark a selected year label, date label, ordered year-range label, identifier or rejected prose cell as source context after checking the original. Date and year-range labels must match the whole retained spreadsheet cell under its Date or Year context; a lexical fragment or inferred period is not enough. Spreadsheet prose must match the whole retained text cell at its exact sheet and address; PDF prose keeps its source span. Rejected prose may retain its original assumption-basis annotation as context only; it must have no metric, entity, unit, currency, scale, definition or semantic scope and cannot be a projected numeric assertion. A year, date or year-range label or identifier with any basis annotation remains ineligible. Signed source coverage must count contextual decisions separately from reviewed numeric assertions. This is a host decision in the dedicated DD workflow, not a public MCP tool or an approved Figure. Other unresolved values remain unresolved; source reads do not establish actual versus forecast meaning.',
        'A host may submit up to 100 selected numeric readings for one human batch decision. A spreadsheet candidate.raw can be printed display text, such as 30.2%, while sourceRawLexeme is the sealed stored cell value, such as 0.3015873015873016. The proposed expectedRawLexeme must use that stored value, never the rounded display; review the exact original cell and receipt before filing. Each reading still needs its exact original source unit (spreadsheet cell or native PDF span) and complete period, unit, basis and definition evidence; the batch publishes one selected review receipt only after every item passes. One rejected or stale item leaves the source selection unchanged. Unknown currency or meaning stays unresolved, and a reviewed reading does not by itself approve a report Figure. This host workflow is not a public MCP tool.',
      ],
      [RETRIEVAL_ATTEMPTS, LITERAL_SOURCE_CONTEXT, ASSET_OWNERSHIP],
    );
  }

  if (workflow === 'folders') {
    return withReference(
      header,
      [
        '## Workflow: folders',
        '1. Folders are an HTTP API under `/api/v2`, not MCP tools. Authenticate with `x-api-key` (or a Bearer session). A key bound to an app acts for that app and its org; a key scoped to a folder sees only that folder and its descendants. A key without an app uses your personal default app, created on first use.',
        '2. Create your folder tree with `PUT /api/v2/folders/by-key/{key}` or `POST /api/v2/folders/ensure-path`, using your own stable keys. Both are idempotent, so retry them freely.',
        '3. Upload files with `POST /api/v2/folders/{id}/sources`, or file a version that already exists in the same partition with `POST /api/v2/folders/{id}/sources/attach`. Filing is free. Analyse each version with `POST /api/v2/sources/{v}/analyze` and `folder_id` in the body; unanalysed sources are listed in `not_searched` rather than searched.',
        '4. Ask questions with `POST /api/v2/folders/{id}/query`, which returns citations bound to exact source spans. Open, preview, share and trace those citations with the citation, preview, share and trace routes below.',
        '5. For a drafted answer, call `POST /api/v2/folders/{id}/generate`. Only claims bound to a quoted source passage are published; the rest appear as gaps.',
        '6. Keep agent context in folder memory with `POST /api/v2/folders/{id}/memory`. Memory notes are context for later calls and are never evidence for a claim.',
        'Credits: filing, attaching, query, statement traces, model evaluation and published answers you write yourself cost 0; generation costs 5; folder analysis costs are listed below.',
      ],
      [
        'Apps, keys and identity. Org owners and admins manage apps and keys with `POST /api/v2/apps`, `GET /api/v2/apps` (optional `?org_id=`), `GET /api/v2/apps/{id}`, `POST /api/v2/apps/{id}/keys`, `GET /api/v2/apps/{id}/keys` and `DELETE /api/v2/apps/{id}/keys/{keyId}`. An app has a name, a slug, up to 20 domains and up to 50 exact `allowed_origins`. A new key is shown once and can carry `folder_id`, `expires_at` and a description. A key created by an app key cannot hold permissions that key lacks. Key permissions are `read`, `write`, `verify`, `memory` and `admin`; writes need `write`, reads need `read`, and a missing permission returns 403 `KEY_SCOPE_DENIED`. Revoking a key takes effect immediately. A folder, source, citation or memory note outside the key\'s reach returns 404 (for example `FOLDER_NOT_FOUND` or `SOURCE_NOT_IN_SCOPE`), never 403, so folders cannot be enumerated. `x-webcite-actor` (1 to 191 characters, no surrounding spaces, otherwise 400 `INVALID_ACTOR`) labels your end user for audit and memory authorship on app keys and never authorises anything. When an app has `allowed_origins`, a request that sends an `Origin` header not on the list fails with 403 `ORIGIN_NOT_ALLOWED`; a request without an `Origin` header is not checked.',
        'Signed requests. An app can require signatures; it then rejects unsigned calls with 403 `SIGNATURE_REQUIRED`. Send `x-webcite-signature: base64url(payload).base64url(HMAC-SHA256(secret, payload part))`, where the payload is the JSON object `{aud: "webcite-app-request", applicationId, method, path, requestHash, actor, expiresAt, nonce}` with no other fields. `applicationId` is the app id or its slug. `method` is upper case. `path` is the request path exactly as sent, including the query string. `requestHash` is the lower-case hex sha256 of the exact raw request body (of the empty string when there is no body); multipart uploads are hashed byte for byte, and a signed upload above 101 MiB fails with 413 `PAYLOAD_TOO_LARGE`. `actor` equals the `x-webcite-actor` header, or null when you send none. `expiresAt` is in Unix seconds, later than now and at most 60 seconds ahead. `nonce` is a UUID used once. A bad signature fails with 403 `SIGNATURE_INVALID` and a reused nonce with 403 `SIGNATURE_REPLAYED`. Apps imported from an earlier product integration have the slug `product-<product>` and require signed requests. An API key that is not bound to an app but is owned by the service account of such an imported app acts as that app on folder routes and follows the same signature, origin and actor rules. When that key owns several imported apps, send `x-webcite-application` with the app id or slug; if it is missing or matches none of them, the call fails with 409 `APPLICATION_AMBIGUOUS` and the body lists `applications [{id, slug}]`.',
        'Folders and ensure-path. `PUT /api/v2/folders/by-key/{key}` (URL-encode the key) ensures one folder: 201 when it is created and 200 when it already exists, without changing its name, metadata or isolation. When the body names a `parent` and the key already exists under another parent, it fails with 409 `FOLDER_PARENT_CONFLICT`; without `parent` the call only resolves the key and returns 404 when it is absent. A parent is `{key}`, `{id}` or null for the top level. `POST /api/v2/folders/ensure-path` ensures a chain of 1 to 32 distinct keys node by node and returns the leaf with its `path`; rerunning it after a partial failure is safe. Read folders with `GET /api/v2/folders/{id}`, `GET /api/v2/folders/by-key/{key}` and `GET /api/v2/folders?parent_id=&kind=&cursor=&limit=&include_archived=`, which lists direct children 1 to 100 at a time (default 50) with `next_cursor`. `PATCH /api/v2/folders/{id}` changes `name`, `metadata` or `archived`; archiving hides a folder from listings and never deletes or unfiles anything. `POST /api/v2/folders/{id}/move {parent}` moves a folder without changing its partition: a move that would change a non-isolated folder\'s partition fails with 409 `FOLDER_PARTITION_MOVE`, and a move under its own subtree with 409 `FOLDER_MOVE_CYCLE`. When the object a folder stands for changes custody, for example a deal reassigned to another client, `POST /api/v2/folders/{id}/rehome {parent, reason}` (admin permission, app-level keys only, audited with the calling key and user) archives the folder and its subtree in their own partition with every filing, citation and memory kept, releases their keys as `rehomed:<id>` (a reserved prefix; nothing can be created or moved under a rehomed folder, 409 `FOLDER_REHOMED`), and creates a new empty folder with the same key under `parent` in the target partition. Its `refile` list names every source filed in the old subtree, folder filings and legacy context-path bindings alike; register each again in the new partition, which creates new versions and runs and charges analysis there again. Rehome is not a revocation: readers of the old partition still see the old subtree, so remove sources from that partition when the reassignment is for confidentiality. Repeating a rehome with the same `parent` returns the committed result, including the `refile` list as it was committed, with `already_rehomed: true` (409 `FOLDER_REHOME_RECORD_MISSING` if that record is gone); another target fails with 409 `FOLDER_ALREADY_REHOMED`, a target in the same partition with 409 `FOLDER_REHOME_SAME_PARTITION`, and an isolated folder with 409 `FOLDER_REHOME_ISOLATED`. Keys and names are at most 191 characters, `kind` at most 32 characters, metadata at most 16 KB of JSON, and depth at most 32 (422 `FOLDER_DEPTH_EXCEEDED`). A folder-scoped key cannot create or move folders at the top level. Invalid bodies return 400 `INVALID_REQUEST` with `issues`.',
        'Partitions. A folder created with `isolated: true` starts its own custody partition. A non-isolated top-level folder lives in the app\'s root partition, and every other folder shares its parent\'s partition. Sources, analyses and citations never mix across partitions; a query over several partitions runs once per partition. Workspaces imported from an earlier product integration are isolated root folders keyed `<workspaceKind>:<workspaceId>` in their existing partition, and their imported context paths become nested folders keyed `<objectType>:<id>`, one per path segment.',
        'Folder sources. `POST /api/v2/folders/{id}/sources` takes multipart `file` and `external_source_key`, with optional `idempotency_key` (sha256 hex), `relative_path`, `batch_id` and `bytes_hash`, up to 100 MB. It registers the file in the folder\'s partition and files it in the folder at no charge. When `bytes_hash` differs from the uploaded bytes, intake fails with 409 `BYTES_HASH_MISMATCH`. The same bytes under the same `external_source_key` in the same partition always give the same `source_version_id` with no second charge. `POST /api/v2/folders/{id}/sources/batches` declares an immutable manifest of up to 500 files, and `GET /api/v2/folders/{id}/sources/batches/{batchId}` reports each file as pending, stored, analysis_selected, changed or unavailable. `POST /api/v2/folders/{id}/sources/attach {source_version_id}` files an existing version from the same partition with no new charge, and the folder reuses its existing analysis. `GET /api/v2/folders/{id}/sources?include_descendants=true` lists one row per filing with `relation` (self or descendant), `partition`, `binding` (`folder` or `legacy_context`), `selected` and `analysis.state` (complete, running or not_started), paged with `cursor` and `limit`. Every folder read sees each filing once, including bindings imported from earlier product integrations. `GET /api/v2/folders/{id}/sources/{external_source_key}` returns the selected version, its analysis receipt, any analysis recovery state and the folders that file it. `DELETE /api/v2/folders/{id}/sources/{external_source_key}?expected_source_version_id=` unfiles a source from that folder only. `POST /api/v2/folders/{id}/sources/remove {external_source_key, expected_source_version_id}` removes a source filed in the folder\'s scope from the whole partition, deactivating every filing of it; the version and its analysis stay retained for citations already issued. A stale `expected_source_version_id` fails with 409.',
        'Source analysis. Per-version routes are scoped by `folder_id`, as a query parameter on GET and a body field on POST: `POST /api/v2/sources/{v}/analyze`, `GET .../candidates`, `GET .../units`, `GET .../assertions`, `GET .../numeric-occurrences`, `POST .../model-inputs`, `POST .../figure-inputs`, `POST .../figure-coverage`, `GET .../metric-definitions`, `POST .../metric-definitions/adopt`, `POST .../reviews`, `POST .../reviews/batch` and `POST .../reviews/context`. A version not filed in the folder\'s scope fails with 404 `SOURCE_NOT_IN_SCOPE`. `POST /api/v2/folders/{id}/models/evaluate` and `POST /api/v2/folders/{id}/models/{receiptId}/verify` evaluate a model over sources that must all be filed in the folder\'s scope, at 0 credits. For sources analyzed on the native path (PDFs, office documents, slides and plain text; spreadsheet files, including CSV and TSV, take the spreadsheet path instead), repeating `POST /api/v2/sources/{v}/analyze` for the same source and reader output reuses the stored number inventory and graph, so it returns the same numeric occurrence, interpretation and graph revision ids instead of a 409 conflict. After Webcite ships a new native number extractor, graph engine or initial interpretation version, the next native-path analyze stores new revisions under new ids; earlier analysis receipts and the ids they reference stay readable. Spreadsheet-path numeric occurrence ids do not yet carry an extractor version and are not read first; that follows in a later change.',
        'Query and citations. `POST /api/v2/folders/{id}/query {text, scope, source_version_ids?, max_hops, limit, memory?}` searches the folder\'s filed sources through the context graph at 0 credits. `text` is at most 2,000 characters, `scope` defaults to `{include_descendants: true, include_ancestors: false}`, `max_hops` is 0, 1 or 2 (default 1) and `limit` is 1 to 20 (default 10). Each citation id is `cit_` plus a sha256 over the answer revision and the fragment, so a replayed query over unchanged analysis returns the same ids. A citation carries `source_version_id`, `unit_id`, `span {start, end, page, bbox}` in code points (any field can be null), `quote`, the `folder_id` where the source is filed and its `relation` (self, ancestor or descendant). Sources that were not searched are listed in `not_searched` with a reason (analysis_pending, superseded, unavailable or source_limit), never dropped silently; at most 200 sources are searched per partition. With `memory: true` the response also returns `memory`, up to 20 current notes from the folder and its ancestors, and `memory_refs`; notes are context, never citations. `GET /api/v2/citations/{citation_id}` returns a citation issued by any folder route (query, generate or a published answer); pass `folder_id` to find a citation indexed only by a trace.',
        'Previews and links. `GET /api/v2/citations/{citation_id}/preview` and `GET /api/v2/sources/{v}/preview?folder_id=&unit_id=&span=start-end` return the unit text, the highlight with PDF line boxes when they align, and a signed `render_url`. `GET /api/v2/sources/{v}/content?folder_id=` returns `{url, expires_at, file_name, media_type, byte_length, bytes_hash}` with a signed link to the original; a superseded version fails with 409 `SOURCE_VERSION_SUPERSEDED` unless you pass `historical=true` and a citation filed in the folder\'s scope still references it. Signed source links (`/api/v2/signed/sources/{token}`) last 5 minutes. `POST /api/v2/sources/{v}/share` and `POST /api/v2/citations/{citation_id}/share` take `{expires_in, folder_id?}`, where `expires_in` is 60 seconds to 30 days (default 7 days), and return 201 with a read-only `url` at `/api/v2/share/{token}` plus `expires_at`. Neither link type needs an API key, and a token of one type never opens the other. A folder citation (`cit_...`) can be shared by any caller that can read it. A uuid citation is one of your own `/api/v1` citations; it cannot be shared by a folder-scoped key or with `folder_id`. A link resolves only inside the partition it was issued for. An invalid, expired or revoked share link returns 404 `SHARE_LINK_INVALID`, and a signed source link returns 403 `SIGNED_LINK_INVALID`. When Webcite rotates the link secret, every outstanding link of both kinds stops working.',
        'Verification against a folder. `POST /api/v1/verify` and `POST /api/v1/verify/batch` accept `evidence_scope {folder_id, include_descendants}` (default true) and need the `verify` permission. With it, verify returns folder citations for the claim with `grounding: "folder"`, `support: "not_checked"` and `verdict: null`; it does not produce a stance or verdict for folder evidence. Batch binds each item that has no source of its own to the best folder citation for its quote, and an item with no match gets an explicit error. Without `evidence_scope` both routes behave as before.',
        'Traces and provenance. `GET /api/v2/answers/{answer_id}/trace?depth=&folder_id=` (depth 1 to 8, default 5) returns nodes and edges from answer to claim, citation, source version, analysis receipt and operation, with graph snapshots, claim relations and memory notes; citation nodes issued at folder scope carry their quote, span, filing folder and relation. `GET /api/v2/sources/{v}/lineage` returns the versions a source derives from, the versions derived from it and the version chain of its asset. `POST /api/v2/folders/{id}/change-impact {source_version_id}` lists, across the partition, the stored answers whose evidence includes that version (each with its citations and affected claims) and the active memory notes resting on it, with a `coverage` flag. `GET /api/v2/folders/{id}/claim-relations` lists claim relations in the folder\'s partition. `POST /api/v2/folders/{id}/trace/statement {text, citation_ids?, depth?}` builds a provenance graph for one sentence of your deliverable with no model call and no credits; without `citation_ids` the text must match a stored answer exactly, ignoring case and whitespace. Unknown credits are null and counted separately (`unknown_credit_operations`); they are never reported as 0.',
        'Folder memory. `POST /api/v2/folders/{id}/memory {body, source_refs[{citation_id} | {source_version_id}], ttl_days, tags}` writes a note linked to the citations, source versions and claims it rests on. It needs the `memory` permission; `ttl_days` is 1 to 3,650 (default 365), with up to 25 refs and 20 tags. Every referenced source must be the current analysed version, otherwise the call fails with 409 `MEMORY_SOURCE_NOT_CURRENT` or `SOURCE_ANALYSIS_INCOMPLETE`. `GET /api/v2/folders/{id}/memory?include_ancestors=true&author=&cursor=` reads notes of the folder and its ancestors in the same partition, including notes imported from earlier product integrations; expired notes come back with `freshness: "stale"`. `PATCH /api/v2/memory/{note_id} {expected_revision, body, ...}` revises a note and fails with 409 `MEMORY_REVISION_CONFLICT` on a stale or superseded revision. Every note has `evidence_status: "unverified"`: memory is context for later calls and is never evidence for a claim.',
        'Grounded generation. `POST /api/v2/folders/{id}/generate {instruction, context?, scope, source_version_ids?, memory, output, json_schema?, max_tokens, model_hint?, stream, write_memory?}` retrieves passages from the folder\'s context graph, drafts with the model and publishes only grounded claims. It needs the `write` permission. `memory` is include or exclude (default include), `output` is text or json (default text, and `json_schema` only with json), and `max_tokens` is 256 to 8,192 (default 2,048). `max_tokens` is the answer budget: the model call allows up to twice it, capped at the model\'s output limit, so the claims Webcite checks after the answer fit, and the answer itself is not cut at exactly `max_tokens`. If the token limit cuts the claim list off (`draft.stop_reason` max_tokens), the complete claims before the cut are grounded as usual, the rest are never checked, `draft.claims_parse_error` is claims_block_truncated and the status is at most partially_grounded. The model writes its claims as one JSON array between ===CLAIMS=== and ===END_CLAIMS===, and text after the end line is never read as claims. If more than one claims array appears between the two lines, none is chosen and `claims_parse_error` is claims_block_ambiguous. Any other unreadable claim list (`claims_parse_error` claims_block_missing, claims_block_not_json_array, claims_block_invalid_json or claims_block_ambiguous) grounds no claim, so the status is insufficient_evidence. Each claim is supported, partial or unsupported, with reasons, decided by quote binding only (`support_basis.semantic_entailment` is not_checked). A partial claim is published with a `[Partially supported: ...]` marker; an unsupported claim appears in the answer text only as `[Gap: ...]` and is still listed in `claims` with a null `claim_id`. The status is grounded, partially_grounded or insufficient_evidence. When no passage is retrieved, the status is insufficient_evidence, the model is not called and nothing is charged. When the model answers but no claim is grounded, the status is also insufficient_evidence and nothing is published, but the call is charged. Generation costs 5 credits, held before the model call and settled once: 5 whenever the model answers, 0 when the call fails without output (502 `GENERATION_MODEL_FAILED`), and null when the provider outcome is unknown (502 `GENERATION_OUTCOME_UNKNOWN` with `operation_id`). With `stream: true` the route sends server-sent events: `text_delta` (the unverified draft), then `citation` events, then `claim` events, then `answer_complete` with the full response, or `error`; validation, permission and credit errors still return as ordinary JSON before the stream opens. `POST /api/v2/folders/{id}/answers {claims[{text, citations[{source_version_id, source_unit_id?, quote}]}], ...}` grounds and publishes an answer you wrote yourself, at no charge. `write_memory.enabled` (needs the `memory` permission) saves the published answer as a folder memory note linked to its citations, readable with `GET /api/v2/folders/{id}/memory` and passed to later generate calls as context; nothing is written for insufficient_evidence. Citations from generated and published answers are full folder citations: they open with `GET /api/v2/citations/{id}`, previews, traces and share links.',
        'Folder analysis. `POST /api/v2/folders/{id}/analysis/conflicts`, `.../classify`, `.../gaps` and `.../contradictions` run over the sources filed in the folder and, by default, its descendants (at most 200 sources). conflicts and contradictions list unreadable sources in `not_searched`; classify and gaps report them per item with `state` and `code`. For contradictions, a source with no published numeric projection is scanned through the verified, company-wide (total, standalone or unknown role, no breakdown) figures of its retained automatic-extraction result at the selected receipt; other figures are counted in `automatic_needs_review_count` and `automatic_scope_excluded_count` and not scanned. Each pair side carries its `origin` (numeric_projection or automatic_extraction) and `role_unknown`; treat a pair with a role_unknown side as needing confirmation. A retained result that read the source only partly (incomplete physical coverage, failures or unavailable values) is listed in `partially_searched`. A source with numbers but no published or retained assertions is listed in `not_searched` as numeric_assertions_unpublished, and one whose retained result has no figures as automatic_extraction_no_figures. Projection and automatic figures are not compared with each other. `coverage: "unknown"` means an empty result is not an all-clear; `coverage_status` is complete, incomplete or no_assertions, with `coverage_reasons` (sources_not_searched, automatic_extraction_partial, unresolved_groups, automatic_figures_need_review, automatic_figures_not_company_wide, mixed_origins_not_compared, no_numeric_assertions), and is never complete when nothing was scanned. conflicts costs 1 credit, classify 1 per readable document, gaps 1 per readable document plus 1, and contradictions is free. A failed call releases its reserved credits.',
        'Usage. `GET /api/v2/usage?folder_id=&include_descendants=true&from=&to=` returns per-folder and subtree credit totals over the half-open window from `from` to `to`. Each operation is attributed to exactly one folder, so subtree totals never count it twice, and filing a source another folder already analysed adds 0 to the folder that reuses it. These operations on one source version are attributed to the folder the source is filed in, including when a background job does the work: source analysis, candidates, units, preview and model structure reads; automatic extraction and its per-document model call; source findings; source semantics enrichment; numeric review, batch review and contextual review; delegated source analysis, candidates and preview; and OCR rescue preparation. Other operations, such as file parsing, uploads, verification, context queries, numeric assertions and model evaluation, keep the folder of a folder-scoped request or stay unattributed. When the source is filed in several folders, the requesting folder is used if the source is filed there, otherwise the folder it was filed in first; the operation is still counted once. Every operation of one paid document, findings or enrichment run carries the folder its run was given when it opened, so filing or unfiling the source mid-run does not split the run across folders. Credits charged are unchanged. Operations recorded before this rule keep their original attribution and are not backfilled. Operations made before folder attribution, on unfiled sources outside a folder-scoped request, or outside folder routes and not tied to a filed source, are reported in `unattributed` against the partition root as `attribution: "partition"` with `per_folder_split: "unknown"`, never as 0. Unknown settled credits make a total null and are counted in `unknown_operations`. A subtree above 2,000 folders returns 422 `USAGE_SCOPE_TOO_LARGE`.',
      ],
    );
  }

  if (workflow === 'billing') {
    return (
      header +
      [
        '## Reference: billing, accounts and agent checkpoints',
        ...BILLING_REFERENCE,
      ].join('\n')
    );
  }

  return (
    header +
    [
      '## Choose a workflow',
      '- `quick_verify` — fact-check a sentence (most common cold start)',
      '- `document_quote` — bind a quote inside an uploaded document',
      '- `document_review` — check every material claim in an uploaded document',
      '- `source_trace` — find and check the original publication behind a screenshot or slide',
      '- `numeric` — figures and conflict analysis',
      '- `billing` — credits, plan renewal, overage, rate limits, accounting and agent checkpoints (reference)',
      '- `folders`: HTTP API for apps, folder hierarchies, folder sources, citations, memory and grounded generation',
      '',
      'Re-call `webcite_guide` with `{ "workflow": "quick_verify" }` (or document_quote / document_review / source_trace / numeric / billing / folders).',
    ].join('\n')
  );
}

export const WEBCITE_GUIDE_TOOL = {
  name: 'webcite_guide',
  description: `Call this free guide first to choose a Webcite workflow. Use workflow=source_trace to identify the original source of a screenshot or slide; use workflow=document_review to check every claim in an uploaded file. Costs 0 credits.`,
  inputSchema: {
    type: 'object' as const,
    properties: {
      workflow: {
        type: 'string',
        enum: ['quick_verify', 'document_quote', 'document_review', 'source_trace', 'numeric', 'billing', 'folders', 'choose'],
        description: 'Which workflow to explain. Default choose lists options; billing is the account and billing reference; folders is the folder hierarchy HTTP API.',
      },
      question: {
        type: 'string',
        description: 'Optional user question or claim to embed in examples',
      },
    },
  },
};
